<div><label for="{{ $prefix }}_password" class="block text-sm font-medium">New password</label><input id="{{ $prefix }}_password" name="password" type="password" required minlength="12" autocomplete="new-password" class="mt-2 w-full rounded-lg border-slate-300"><p class="mt-2 text-xs text-slate-500">At least 12 characters, including uppercase, lowercase, a number and a symbol.</p></div>
<div><label for="{{ $prefix }}_password_confirmation" class="block text-sm font-medium">Confirm new password</label><input id="{{ $prefix }}_password_confirmation" name="password_confirmation" type="password" required minlength="12" autocomplete="new-password" class="mt-2 w-full rounded-lg border-slate-300"></div>
